@block GyroverRef begin
    # Reference model of the Gyrover (generated by design/gen_ref.py; do not edit by hand).
    #
    # The exact-rolling equations of design/eom.py: a knife-edge wheel that rolls without
    # slipping on the ground plane, a pendulum on the axle, a tilt gimbal on the pendulum and a
    # flywheel in the gimbal, derived with Kane's method. The rolling constraint is built into
    # the generalised speeds, so there is no contact force, no penetration and no slip; the
    # bond graph (RollingDisk on a compliant contact) is compared with this block.
    #
    # Coordinates: heading psi, lean phi, wheel angle gam, pendulum pitch beta (absolute, in the
    # lean frame), tilt tlt (the paper's theta2), speeds u1..u5 their rates and u6 the flywheel rate relative to
    # the gimbal; x, y the wheel centre. M u' = F is solved by an LDL^T elimination below.
    #
    # Inputs and outputs use the paper's coordinates and signs (Tsai, Ferreira and Paredis,
    # IROS 1999), the same as GyroSense on the bond graph: tau1 drives the pendulum against the
    # wheel, tau2 the tilt gimbal against the pendulum, tau3 the flywheel against the gimbal.
    @parameters begin
        R::Real = 0.197, [unit = "m", description = "Wheel radius"]
        m_w::Real = 2.0, [unit = "kg", description = "Wheel mass (rim, tyre, domes)"]
        Jwa::Real = 0.0249, [unit = "kg*m^2", description = "Wheel axial inertia"]
        Jwt::Real = 0.0146, [unit = "kg*m^2", description = "Wheel transverse inertia"]
        m_p::Real = 3.417, [unit = "kg", description = "Pendulum mass (drive unit, battery)"]
        l_p::Real = 0.0939, [unit = "m", description = "Pendulum centre of mass below the axle"]
        a_p::Real = 0.7853981633974483, [unit = "rad", description = "Pitch of the pendulum's principal axes"]
        Jp1::Real = 0.0371, [unit = "kg*m^2", description = "Pendulum principal inertia 1"]
        Jp2::Real = 0.0353, [unit = "kg*m^2", description = "Pendulum principal inertia 2 (axle)"]
        Jp3::Real = 0.0091, [unit = "kg*m^2", description = "Pendulum principal inertia 3"]
        m_g::Real = 0.4, [unit = "kg", description = "Gimbal frame mass"]
        l_g::Real = 0.0, [unit = "m", description = "Gimbal centre below the axle"]
        Jg1::Real = 0.00087, [unit = "kg*m^2", description = "Gimbal inertia about the tilt axis"]
        Jg2::Real = 0.0006, [unit = "kg*m^2", description = "Gimbal inertia about the spin axis"]
        Jg3::Real = 0.0007, [unit = "kg*m^2", description = "Gimbal inertia about its third axis"]
        m_r::Real = 1.2, [unit = "kg", description = "Flywheel mass"]
        Jra::Real = 0.00301, [unit = "kg*m^2", description = "Flywheel axial (spin) inertia"]
        Jrt::Real = 0.00166, [unit = "kg*m^2", description = "Flywheel transverse inertia"]
        g0::Real = 9.81, [unit = "m/s^2", description = "Gravitational acceleration"]
        bsp::Real = 0.0, [unit = "N*m*s/rad", description = "Tyre drilling damping about the ground normal"]
    end
    @inputs begin
        tau1::Real
        tau2::Real
        tau3::Real
    end
    @variables begin
